import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty input
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix: square and binary entries (0 or 1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list (undirected, no self-loops, deduplicated)
    if is_matrix:
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    graph[i].append(j)
    else:
        graph = []
        for i in range(n):
            if i < len(adj):
                nbrs = [v for v in adj[i] if v != i and 0 <= v < n]
                graph.append(list(dict.fromkeys(nbrs)))
            else:
                graph.append([])

    # Precompute degrees
    deg = [len(graph[v]) for v in range(n)]

    # Helper: degree in subgraph induced by a set (given as boolean list)
    def deg_in_set(v, in_set):
        cnt = 0
        for u in graph[v]:
            if in_set[u]:
                cnt += 1
        return cnt

    # DSATUR with bitmask optimization for saturation updates
    def dsatur():
        color = [-1] * n
        colored = [False] * n
        neighbor_color_mask = [0] * n  # bitmask of colors in neighborhood
        saturation = [0] * n           # current saturation degree

        for _ in range(n):
            v = -1
            best_sat = -1
            best_deg = -1
            for u in range(n):
                if not colored[u]:
                    sat_u = saturation[u]
                    deg_u = deg_in_set(u, [not colored[x] for x in range(n)])
                    if sat_u > best_sat or (sat_u == best_sat and deg_u > best_deg) or \
                       (sat_u == best_sat and deg_u == best_deg and u < v):
                        best_sat = sat_u
                        best_deg = deg_u
                        v = u
            if v == -1:
                break

            used_mask = neighbor_color_mask[v]
            c = 0
            while used_mask & (1 << c):
                c += 1
            color[v] = c
            colored[v] = True

            for u in graph[v]:
                if not colored[u]:
                    if not (neighbor_color_mask[u] & (1 << c)):
                        neighbor_color_mask[u] |= (1 << c)
                        saturation[u] += 1
        return color

    # RLF (Recursive Largest First) with set-based operations and randomization for tie-breaking
    def rlf():
        best_coloring = None
        best_k = float('inf')
        # Try multiple random seeds for tie-breaking in RLF
        for seed in range(3):
            random.seed(seed)
            color = [-1] * n
            colored = [False] * n
            uncolored = set(range(n))
            current_color = 0

            while uncolored:
                # Select vertex with max degree in uncolored subgraph, break ties randomly
                uncolored_list = list(uncolored)
                random.shuffle(uncolored_list)
                v = max(uncolored_list, key=lambda x: deg_in_set(x, [y in uncolored for y in range(n)]))
                S = {v}
                U = set()
                W = set()
                for u in uncolored:
                    if u == v:
                        continue
                    adj_to_S = False
                    for s in S:
                        if u in graph[s]:
                            adj_to_S = True
                            break
                    if adj_to_S:
                        W.add(u)
                    else:
                        U.add(u)
                while U:
                    best_u = -1
                    best_score = -1
                    best_deg_in_U = float('inf')
                    for u in U:
                        score = 0
                        for nb in graph[u]:
                            if nb in W:
                                score += 1
                        deg_in_U = deg_in_set(u, [y in U for y in range(n)])
                        if score > best_score or (score == best_score and deg_in_U < best_deg_in_U) or \
                           (score == best_score and deg_in_U == best_deg_in_U and u < best_u):
                            best_score = score
                            best_deg_in_U = deg_in_U
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                for nb in graph[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
                for vertex in S:
                    color[vertex] = current_color
                    colored[vertex] = True
                uncolored -= S
                current_color += 1
            k = max(color) + 1 if n > 0 else 0
            if k < best_k or (k == best_k and (best_coloring is None or color < best_coloring)):
                best_k = k
                best_coloring = color[:]
        return best_coloring

    # Smallest-Last ordering with greedy coloring (Matula & Beck)
    def smallest_last():
        if n == 0:
            return []
        remaining = set(range(n))
        degree_curr = deg[:]
        max_deg = max(degree_curr) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree_curr[v]
            if d < len(bins):
                bins[d].append(v)
        ptr = 0
        order = []
        for _ in range(n):
            while ptr < len(bins) and not bins[ptr]:
                ptr += 1
            if ptr >= len(bins):
                break
            v = bins[ptr].pop()
            order.append(v)
            remaining.remove(v)
            for u in graph[v]:
                if u in remaining:
                    d = degree_curr[u]
                    if u in bins[d]:
                        bins[d].remove(u)
                    degree_curr[u] -= 1
                    d_new = degree_curr[u]
                    if d_new < len(bins):
                        bins[d_new].append(u)
                    else:
                        while len(bins) <= d_new:
                            bins.append([])
                        bins[d_new].append(u)
            if ptr > 0 and not bins[ptr]:
                ptr -= 1
        colored = [False] * n
        colors = [-1] * n
        for v in reversed(order):
            used = [False] * (n + 1)
            for u in graph[v]:
                if colored[u]:
                    c = colors[u]
                    if c < n + 1:
                        used[c] = True
            c = 0
            while c < n + 1 and used[c]:
                c += 1
            colors[v] = c
            colored[v] = True
        return colors

    # Kempe chain refinement focused on eliminating the last color class (limited iterations)
    def kempe_refine(coloring):
        if n == 0:
            return coloring
        colors = coloring[:]
        k = max(colors) + 1 if n > 0 else 0
        improved = True
        # Limit iterations to avoid excessive runtime; 3 is sufficient for N<=100
        for _ in range(3):
            if not improved or k <= 1:
                break
            improved = False
            color_class = [v for v in range(n) if colors[v] == k - 1]
            if not color_class:
                k -= 1
                continue
            # Process vertices in random order to avoid bias
            random.shuffle(color_class)
            for v in color_class:
                # Try direct move to any lower color
                for c in range(k - 1):
                    conflict = False
                    for u in graph[v]:
                        if colors[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        colors[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains for each lower color
                for c in range(k - 1):
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for nb in graph[x]:
                            if not visited[nb] and (colors[nb] == c or colors[nb] == k - 1):
                                visited[nb] = True
                                queue.append(nb)
                    # Check safety: no neighbor of v with color c in the component
                    safe = True
                    for nb in graph[v]:
                        if colors[nb] == c and visited[nb]:
                            safe = False
                            break
                    if safe:
                        for x in component:
                            if colors[x] == c:
                                colors[x] = k - 1
                            elif colors[x] == k - 1:
                                colors[x] = c
                        improved = True
                        break
                if improved:
                    break
            k = max(colors) + 1 if n > 0 else 0
        return colors

    # Run all algorithms and collect candidates
    candidates = []
    try:
        c1 = dsatur()
        k1 = max(c1) + 1 if n > 0 else 0
        candidates.append((k1, c1))
    except Exception:
        pass
    try:
        c2 = rlf()
        k2 = max(c2) + 1 if n > 0 else 0
        candidates.append((k2, c2))
    except Exception:
        pass
    try:
        c3 = smallest_last()
        k3 = max(c3) + 1 if n > 0 else 0
        candidates.append((k3, c3))
    except Exception:
        pass

    # Refine each candidate with Kempe chains
    refined = []
    for k, col in candidates:
        try:
            col_refined = kempe_refine(col)
            k_refined = max(col_refined) + 1 if n > 0 else 0
            refined.append((k_refined, col_refined))
        except Exception:
            refined.append((k, col))

    all_candidates = candidates + refined
    if not all_candidates:
        # Fallback: greedy by degree order (Welsh-Powell)
        colors = [-1] * n
        order = sorted(range(n), key=lambda x: (-deg[x], x))
        for v in order:
            used = [False] * (n + 1)
            for u in graph[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            c = 0
            while c < n + 1 and used[c]:
                c += 1
            colors[v] = c
        all_candidates.append((max(colors) + 1 if n > 0 else 0, colors))

    # Select the candidate with the fewest colors; break ties by lexicographical order
    best_k = float('inf')
    best_col = None
    for k, col in all_candidates:
        if k < best_k:
            best_k = k
            best_col = col
        elif k == best_k:
            if best_col is None or col < best_col:
                best_col = col
    return best_col

