import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect if input is adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list and compute degrees
    neighbors = [[] for _ in range(n)]
    deg = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
        deg = [len(neighbors[i]) for i in range(n)]
    else:
        for i in range(n):
            neighbors[i] = list(adj[i])
        deg = [len(neighbors[i]) for i in range(n)]

    # Helper: DSATUR coloring with optimized tie-breaking
    def dsatur_coloring():
        color = [-1] * n
        saturation = [set() for _ in range(n)]
        uncolored = set(range(n))
        # Initial order: degree descending, then index
        order = sorted(uncolored, key=lambda x: (-deg[x], x))
        for v in order:
            if v not in uncolored:
                continue
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u].add(c)
        # Main loop: select by max saturation, then degree in uncolored, then index
        while uncolored:
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat_size = len(saturation[v])
                if sat_size > max_sat:
                    max_sat = sat_size
                    candidates = [v]
                elif sat_size == max_sat:
                    candidates.append(v)
            if len(candidates) > 1:
                max_deg = -1
                new_cands = []
                for v in candidates:
                    d = 0
                    for u in neighbors[v]:
                        if u in uncolored:
                            d += 1
                    if d > max_deg:
                        max_deg = d
                        new_cands = [v]
                    elif d == max_deg:
                        new_cands.append(v)
                candidates = new_cands
            v = min(candidates)  # final tie-break by index
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u].add(c)
        return color

    # Helper: RLF coloring with optimized independent set construction
    def rlf_coloring():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Compute degree in uncolored subgraph
            deg_uncolored = [0] * n
            for v in uncolored:
                d = 0
                for u in neighbors[v]:
                    if u in uncolored:
                        d += 1
                deg_uncolored[v] = d
            # Start with vertex of max degree in uncolored, tie-break by index
            v = max(uncolored, key=lambda x: (deg_uncolored[x], -x))  # -x to prefer higher index? but we want consistent, so use x for min index in tie
            # Actually, we break ties by vertex index (lower first) as per common practice, but the paper doesn't specify.
            # We'll use: max degree, then min index to be deterministic.
            v = max(uncolored, key=lambda x: (deg_uncolored[x], -x))  # higher degree, then lower index (because -x larger for smaller x)
            S = {v}
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                # Check if u is adjacent to any in S
                adj_to_S = False
                for w in S:
                    if u in neighbors[w]:
                        adj_to_S = True
                        break
                if adj_to_S:
                    W.add(u)
                else:
                    U.add(u)
            # Expand S
            while U:
                best_u = None
                best_score = -1
                for u in U:
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    if score > best_score or (score == best_score and (best_u is None or u < best_u)):
                        best_score = score
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Helper: smallest-last ordering (degeneracy ordering)
    def smallest_last_ordering():
        deg_copy = deg[:]
        max_deg = max(deg) if n > 0 else 0
        bins = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg_copy[v]
            if d <= max_deg:
                bins[d].add(v)
        min_d = 0
        order = []
        removed = [False] * n
        for _ in range(n):
            while min_d <= max_deg and not bins[min_d]:
                min_d += 1
            if min_d > max_deg:
                break
            v = bins[min_d].pop()
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    d_u = deg_copy[u]
                    bins[d_u].remove(u)
                    deg_copy[u] -= 1
                    bins[deg_copy[u]].add(u)
                    if deg_copy[u] < min_d:
                        min_d = deg_copy[u]
        return order  # removal order; coloring in reverse

    # Helper: Welsh-Powell ordering (sort by degree descending)
    def welsh_powell_ordering():
        return sorted(range(n), key=lambda x: (-deg[x], x))

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Helper: Kempe chain swap for color a and b, starting from vertex v
    def kempe_swap(color, a, b, v):
        if color[v] not in (a, b):
            return None
        stack = [v]
        visited = set()
        comp_color_a = []
        comp_color_b = []
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            if color[node] == a:
                comp_color_a.append(node)
            elif color[node] == b:
                comp_color_b.append(node)
            for nb in neighbors[node]:
                if nb not in visited and color[nb] in (a, b):
                    stack.append(nb)
        new_color = color[:]
        for node in comp_color_a:
            new_color[node] = b
        for node in comp_color_b:
            new_color[node] = a
        return new_color

    # Helper: local search with Kempe chains to try to reduce number of colors
    def local_search_kempe(color):
        max_color = max(color) if n > 0 else -1
        if max_color < 0:
            return color
        # Try to eliminate color classes from highest down
        for target_color in range(max_color, 0, -1):
            verts = [v for v in range(n) if color[v] == target_color]
            if not verts:
                continue
            made_change = False
            for v in verts:
                neighbor_colors = set()
                for u in neighbors[v]:
                    if color[u] != -1:
                        neighbor_colors.add(color[u])
                # Try direct reassignment to a lower color
                for c in range(target_color):
                    if c not in neighbor_colors:
                        color[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chains
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue
                    new_color = kempe_swap(color, target_color, c, v)
                    if new_color is not None:
                        # Verify no conflict after swap
                        conflict = False
                        for u in neighbors[v]:
                            if new_color[u] == c:
                                conflict = True
                                break
                        if not conflict:
                            color[:] = new_color
                            made_change = True
                            break
                if made_change:
                    break
            if not made_change:
                break
        return color

    # Try multiple algorithms and pick the best (fewest colors)
    best_coloring = None
    best_num_colors = float('inf')

    # 1. DSATUR
    try:
        col1 = dsatur_coloring()
        num1 = max(col1) + 1 if n > 0 else 0
        if num1 < best_num_colors:
            best_num_colors = num1
            best_coloring = col1[:]
    except:
        pass

    # 2. RLF
    try:
        col2 = rlf_coloring()
        num2 = max(col2) + 1 if n > 0 else 0
        if num2 < best_num_colors:
            best_num_colors = num2
            best_coloring = col2[:]
    except:
        pass

    # 3. Smallest-last ordering + greedy
    try:
        order_sl = smallest_last_ordering()
        col3 = greedy_color(list(reversed(order_sl)))
        num3 = max(col3) + 1 if n > 0 else 0
        if num3 < best_num_colors:
            best_num_colors = num3
            best_coloring = col3[:]
    except:
        pass

    # 4. Welsh-Powell ordering + greedy
    try:
        order_wp = welsh_powell_ordering()
        col4 = greedy_color(order_wp)
        num4 = max(col4) + 1 if n > 0 else 0
        if num4 < best_num_colors:
            best_num_colors = num4
            best_coloring = col4[:]
    except:
        pass

    # Apply local search with Kempe chains to improve
    if best_coloring is not None:
        try:
            col_ls = local_search_kempe(best_coloring[:])
            num_ls = max(col_ls) + 1 if n > 0 else 0
            if num_ls < best_num_colors:
                best_num_colors = num_ls
                best_coloring = col_ls[:]
        except:
            pass

    # Fallback: if nothing worked, use simple greedy
    if best_coloring is None:
        order = list(range(n))
        best_coloring = greedy_color(order)

    return best_coloring
